    "reason": "Bipartite graph on 11 vertices has a partition of size >= 6, which is an independent set"
})

for i, c in enumerate(contradictions):
    print(f"Contradiction {i+1}:")
    print(f"  Constraints: {c['constraints']}")
    print(f"  Reason: {c['reason']}")
    print()

